  ('4b5efa12-d706-48ef-b232-f375c9b4537b', '6932050f-dba1-48a5-8ab0-aab93f5e64c5', 'TROPICAL TERRAIN', 'abandon yourself to the tropical combination of malta orange and muskmelon balanced with passion fruit.', 380, null, null, false, true, 0),
  ('751253d4-5beb-4351-beeb-c3728b2e2a92', '6932050f-dba1-48a5-8ab0-aab93f5e64c5', 'MOCK AND MEDI', 'drink showcases simply outstanding and delicious combination of hibiscus tea, oregano and loaded with nutrient from pineapple juice.', 385, null, null, false, true, 1),
  ('6640c7fe-ce43-4869-92de-f437c9433228', '6932050f-dba1-48a5-8ab0-aab93f5e64c5', 'MORAL FLORAL', 'the drink is tart and refreshing with the infusion of butterfly pea flower in with apple juice with hint of elderflower.', 385, null, null, false, true, 2),
  ('9a600ff4-852a-4182-845b-ea2070bdfd5b', '6932050f-dba1-48a5-8ab0-aab93f5e64c5', 'TODI THRILL', 'the mocktail overflows with the aromas of the holiday it''s an exortic twist of lychee juice, vanilla and cinnamon.', 385, null, null, false, true, 3),
  ('c67ee3d3-0934-41cc-90b6-623bca2a2642', '6932050f-dba1-48a5-8ab0-aab93f5e64c5', 'BERRY MIST', 'the berrylicious drink with the flavor of fresh raspberries, basil, apple and topped up with sparkling water.', 385, null, null, false, true, 4),
  ('7fa2af90-573b-4062-ba5f-9639bdbca10d', '44b09f88-5d78-4958-818b-f829553cca67', 'ARAQUE THATIM', 'gin made mediterranean inspired cocktail with herbaceous notes of parsley and aromatic fennel.', 715, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20132040.png', null, true, true, 0),
  ('c97b5b64-7176-4c7e-a1b7-ffdbe7d5293b', '44b09f88-5d78-4958-818b-f829553cca67', 'POMONA', 'a combination between gin and aperol binded with watermelon and kokum with cheesiness of feta.', 715, null, null, true, true, 1),
  ('750b2636-d0e1-4908-a33d-8fd3e01cd709', '44b09f88-5d78-4958-818b-f829553cca67', 'SHEZMU', 'a tropical punch of fruits like orange and apple in red vino.', 715, null, null, true, true, 2),
  ('5663c941-f682-4871-92c8-3e61f746ef48', '44b09f88-5d78-4958-818b-f829553cca67', 'ESPRESSO MARTINI', 'a 1983s cold caffeinated alcoholic drink which shows a beautiful love story between vodka and coffee.', 715, null, null, true, true, 3),
  ('50519fd2-5449-4a1d-88c6-a4f0bd363eaf', '44b09f88-5d78-4958-818b-f829553cca67', 'SHIBINT', 'a evergreen gin combination between apple and cucumber paired with the emerging herbal note of dill weed.', 770, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20131630.png', null, true, true, 4),
  ('09f22f8b-3363-42c0-8cba-3e6142937ae8', '44b09f88-5d78-4958-818b-f829553cca67', 'BEN CAO JING', 'a hot vodka drink named after famous herbalist,here 6 assorted herbs were paired with elderflower and citrus.', 770, null, null, true, true, 5),
  ('6553d886-19e0-4bb0-a64d-3ac7ea87e691', '44b09f88-5d78-4958-818b-f829553cca67', 'KASSITE', 'a poetic balance of 2 mesmerizing flavour between butterfly pea tea and moroccan tea binded through white vino.', 770, null, null, true, true, 6),
  ('58e51338-94d5-4991-9f11-bec0ebbe9ddd', '44b09f88-5d78-4958-818b-f829553cca67', 'GARIBALDI DE BIBERIYE', 'a tribute to a patriot who united 2 countries, here 2 perfect pairing of muskmelon and orange in gold rum and campari with herbal notes of rosemary.', 825, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20131947.png', null, true, true, 7),
  ('c78d6dac-568c-4ec0-bbfc-ef6e15c81e7e', '44b09f88-5d78-4958-818b-f829553cca67', 'MR GEBALY', 'a tribute to a finest artist of italy,here showcased finest piece of cocktail with apricots infused scotch, campari and sweet vermouth.', 825, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20131727.png', null, true, true, 8),
  ('ac1ebd00-5213-4c76-b7fe-88f54c24a2b0', '44b09f88-5d78-4958-818b-f829553cca67', 'INCIR', 'a deconstructed manhattan cocktail cables with fig infused scotch and sweet vermouth.', 825, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20131825.png', null, true, true, 9),
  ('449c2d58-5f52-4e37-9d6c-c212ea9cec7f', '44b09f88-5d78-4958-818b-f829553cca67', 'OTTOMAN', 'empire which inspired brut grape infused tequila balanced with tangy pomegranate and maple.', 880, 'https://d1hddaam55e99y.cloudfront.net/1076_Screenshot%202026-02-10%20131703.png', null, true, true, 10),
  ('b22afa2a-a214-4f80-81ad-f5839ccfb087', '44b09f88-5d78-4958-818b-f829553cca67', 'GTA', 'a clarified tequila cocktail with freshness of green apple, floral notes of elderflower and paired with tinge spice cumin.', 880, null, null, true, true, 11),
  ('ebaa5768-2554-4138-b116-af02eeac22b3', '44b09f88-5d78-4958-818b-f829553cca67', 'YEMONITE', 'a vino summer drink with fruitiness of passion fruit,pineapple and grapefruit combined with aperol.', 880, null, null, true, true, 12),
  ('a54aacbe-5f82-4b4c-8d8c-e27385ceeaad', '44b09f88-5d78-4958-818b-f829553cca67', 'MEDITERRANEAN MIMOSA', 'peach and grapefruit were blushed with crisp taste of prosecco.', 880, null, null, true, true, 13),
  ('e0618b00-bfc7-4005-82eb-b01f3a8b7ed9', '44b09f88-5d78-4958-818b-f829553cca67', 'OSIRIS', 'a egyptian tiki cocktail with 2 pairing of pumpkin and rum with spices and amaretto.', 880, null, null, true, true, 14),
  ('4f9091a7-235a-4fd8-b9ab-39580a78746c', '44b09f88-5d78-4958-818b-f829553cca67', 'LAPIS LAZULLI', 'a coastal island greece flavours like lychee and jasmine is paired with moscato vino.', 880, null, null, true, true, 15),
